/* Neural synthetic audio; generated locally with Kokoro v1.0. */
window.ISM_BUSINESS_NEURAL={"meeting-decisions":[{"speaker":"Alex","text":"Thanks for joining. The agenda has three items, and our objective is to agree on the launch date.","voice":"kokoro-v1-af_heart","audioUrl":"assets/dialogues/meeting-decisions-turn-0.mp3","sha256":"0ef2e60b06e8e624b98ed93aa706be231a03e74ea4d12b9acf87cf99b6ebef17","bytes":48620,"seconds":5.984},{"speaker":"Jordan","text":"Before we choose a date, could you give us a quick update on testing?","voice":"kokoro-v1-am_michael","audioUrl":"assets/dialogues/meeting-decisions-turn-1.mp3","sha256":"8eeb454899ddaebe236421325c1cad6133b527628bb2df316ddbd2662fd724f4","bytes":34412,"seconds":4.2026666666666666},{"speaker":"Alex","text":"The design work is on track, but the missing client approval is a blocker for testing.","voice":"kokoro-v1-af_heart","audioUrl":"assets/dialogues/meeting-decisions-turn-2.mp3","sha256":"c7165cee5fd51ccfd8d068ecf626faeaecf3abf31be4cf7ca0708556c2ca750d","bytes":39980,"seconds":4.905958333333333},{"speaker":"Jordan","text":"Could you clarify which approval is missing?","voice":"kokoro-v1-am_michael","audioUrl":"assets/dialogues/meeting-decisions-turn-3.mp3","sha256":"cc1f34570e398074f38b408a47264941672cf80b21a7120d838744b4931cc3ef","bytes":22892,"seconds":2.7733333333333334},{"speaker":"Alex","text":"We need approval for the payment screen. Testing that screen is our main priority.","voice":"kokoro-v1-af_heart","audioUrl":"assets/dialogues/meeting-decisions-turn-4.mp3","sha256":"a9281f1f620a19336781994f7f1d4c313b17fcb9b41643aa6e942902f5aef238","bytes":38444,"seconds":4.715333333333334},{"speaker":"Jordan","text":"Then our first action item is to contact the client. Who is the owner of that action?","voice":"kokoro-v1-am_michael","audioUrl":"assets/dialogues/meeting-decisions-turn-5.mp3","sha256":"832ecfa61dd62363ca0efa1d10418cf93211269b0a71fca5e10f08b89e81e334","bytes":45548,"seconds":5.610666666666667},{"speaker":"Alex","text":"I am. I will follow up with the client tomorrow morning and ask for a reply by Tuesday.","voice":"kokoro-v1-af_heart","audioUrl":"assets/dialogues/meeting-decisions-turn-6.mp3","sha256":"10f1ec26c21c7a6e66ddaae5d1026993f0311434aebf58ad6afffdaf5e0110ff","bytes":41900,"seconds":5.1433333333333335},{"speaker":"Jordan","text":"If they reply by Tuesday, can we keep the current timeline?","voice":"kokoro-v1-am_michael","audioUrl":"assets/dialogues/meeting-decisions-turn-7.mp3","sha256":"e9cb30fdb1956cbdad12c610072fc7ac06b8b71afb2d6ac21369e06cf874f176","bytes":30380,"seconds":3.712},{"speaker":"Alex","text":"Yes. Otherwise, we need two extra days for testing.","voice":"kokoro-v1-af_heart","audioUrl":"assets/dialogues/meeting-decisions-turn-8.mp3","sha256":"f3bcd6b10831a1d8ce5ffb5be74f20f59f95fae21be19e657e007d6e8831b016","bytes":29420,"seconds":3.593958333333333},{"speaker":"Jordan","text":"Let us record that risk and review the timeline on Wednesday.","voice":"kokoro-v1-am_michael","audioUrl":"assets/dialogues/meeting-decisions-turn-9.mp3","sha256":"da81cd22ed77f6e3cff3afac846beb4c16ff26eac5aa81a67dd1591e3d834e27","bytes":32684,"seconds":3.989333333333333},{"speaker":"Alex","text":"Agreed. I will send a written update after I hear from the client.","voice":"kokoro-v1-af_heart","audioUrl":"assets/dialogues/meeting-decisions-turn-10.mp3","sha256":"fbfa794a1749198f5b413d0fffee360ce275cda92552d40e58b65f8f558d6b01","bytes":31340,"seconds":3.8179583333333333},{"speaker":"Jordan","text":"Let us wrap up. You will contact the client, and we will review the launch date on Wednesday.","voice":"kokoro-v1-am_michael","audioUrl":"assets/dialogues/meeting-decisions-turn-11.mp3","sha256":"9ee5f54bb90e7c0b1f54fb46efd25743fbcc063f0066ef29b56de7fd96b4f82e","bytes":46892,"seconds":5.781333333333333}],"deadline-negotiation":[{"speaker":"Sam","text":"The deadline for the full report is Friday. Can your team meet it?","voice":"kokoro-v1-af_bella","audioUrl":"assets/dialogues/deadline-negotiation-turn-0.mp3","sha256":"161b1353c3b2ac34b4c1f575861e09c3be677fe052fafd5eb9708fbb3f7994e4","bytes":30956,"seconds":3.7853333333333334},{"speaker":"Taylor","text":"Our workload is high this week, and we do not have the capacity for a complete analysis by Friday.","voice":"kokoro-v1-am_fenrir","audioUrl":"assets/dialogues/deadline-negotiation-turn-1.mp3","sha256":"a28cd96a35ab49f6eb0cdde2c0b8eff5145c4664ce112bca88561f4fae3ca0c1","bytes":48620,"seconds":5.9939583333333335},{"speaker":"Sam","text":"The leadership team needs something for its Friday meeting.","voice":"kokoro-v1-af_bella","audioUrl":"assets/dialogues/deadline-negotiation-turn-2.mp3","sha256":"337a5cc4c5474e8bbcd8bee934fd34ede98933b260f68e2a4b6fab35018d71af","bytes":25580,"seconds":3.1026666666666665},{"speaker":"Taylor","text":"Understood. Could we reduce the scope of the first deliverable and send a summary?","voice":"kokoro-v1-am_fenrir","audioUrl":"assets/dialogues/deadline-negotiation-turn-3.mp3","sha256":"f0d47f151e3b622451409fd1fb36a2d96ac25c88aa2698d90ab4d7bb31a00c37","bytes":38636,"seconds":4.737333333333333},{"speaker":"Sam","text":"That may work, but when would the complete report arrive?","voice":"kokoro-v1-af_bella","audioUrl":"assets/dialogues/deadline-negotiation-turn-4.mp3","sha256":"18c060b47aa6d9f0a327215814a18dc21061a46c08774b4dbfbdc2b1ac140d66","bytes":26540,"seconds":3.2293333333333334},{"speaker":"Taylor","text":"Could we request an extension and push back the full report to Tuesday?","voice":"kokoro-v1-am_fenrir","audioUrl":"assets/dialogues/deadline-negotiation-turn-5.mp3","sha256":"9f2e02cc67dffd2c62a15b0137d9729f9c0d17877b5aeee6afcd1d847e3d125e","bytes":33836,"seconds":4.137958333333334},{"speaker":"Sam","text":"Tuesday is acceptable if the summary arrives before our meeting.","voice":"kokoro-v1-af_bella","audioUrl":"assets/dialogues/deadline-negotiation-turn-6.mp3","sha256":"51f69a80f0c0b82f15380e1b31379d4669b5dcb1a7a2d167bea196ebf6b917c6","bytes":33644,"seconds":4.124625},{"speaker":"Taylor","text":"We can bring forward the summary to Friday morning. That is feasible.","voice":"kokoro-v1-am_fenrir","audioUrl":"assets/dialogues/deadline-negotiation-turn-7.mp3","sha256":"7f25d4fab778753f9078550be6a5965afb3cd890636a085838f0063357ec7617","bytes":31724,"seconds":3.869291666666667},{"speaker":"Sam","text":"What is the trade-off in the summary?","voice":"kokoro-v1-af_bella","audioUrl":"assets/dialogues/deadline-negotiation-turn-8.mp3","sha256":"6c4c0a0a9958f0c7b3726041b6123fe08e8b4adcd4f24233b63ad2123e545b25","bytes":16172,"seconds":1.9373333333333334},{"speaker":"Taylor","text":"It will include the main findings, but not the detailed comparisons. We can make a firm commitment to the full analysis on Tuesday.","voice":"kokoro-v1-am_fenrir","audioUrl":"assets/dialogues/deadline-negotiation-turn-9.mp3","sha256":"ec1dff1aa7368073c9c324c99b9d973b8e0b0e01f74eca385a064f8d9db3697c","bytes":64172,"seconds":7.934},{"speaker":"Sam","text":"Agreed: a summary on Friday morning and the full report on Tuesday.","voice":"kokoro-v1-af_bella","audioUrl":"assets/dialogues/deadline-negotiation-turn-10.mp3","sha256":"ac332634f82e7ffb23e6d97c8715f0e7c9de1e74b92ad1d0085bb8d32a92d874","bytes":35948,"seconds":4.415291666666667},{"speaker":"Taylor","text":"Thank you. I will send the revised schedule today and confirm both deliverables.","voice":"kokoro-v1-am_fenrir","audioUrl":"assets/dialogues/deadline-negotiation-turn-11.mp3","sha256":"8f76ac28843907381833078db3d5a9105a99ea9dd1e6376c62944ae4b59b5f0d","bytes":38444,"seconds":4.714666666666667}],"presenting-results":[{"speaker":"Morgan","text":"Our key takeaway is that growth must remain profitable. Let me start with the revenue figure.","voice":"kokoro-v1-af_nicole","audioUrl":"assets/dialogues/presenting-results-turn-0.mp3","sha256":"2a7cff289daebfc53a18b1d93c1ed5ad6a250fefb3fbaa1429f0303d36129745","bytes":71852,"seconds":8.885333333333334},{"speaker":"Casey","text":"What period does this figure cover?","voice":"kokoro-v1-am_puck","audioUrl":"assets/dialogues/presenting-results-turn-1.mp3","sha256":"9dd3a8aaa10f1fbe2aa8840b0e8372a39e9af18eb38dd36afa6042b29012703c","bytes":16748,"seconds":2.008625},{"speaker":"Morgan","text":"This quarter. Revenue rose eight percent compared with last quarter, so we exceeded our revenue target.","voice":"kokoro-v1-af_nicole","audioUrl":"assets/dialogues/presenting-results-turn-2.mp3","sha256":"07b66e66c75726faaf638d58bbaf37d580c194e095953739853876881a2cf153","bytes":76844,"seconds":9.513958333333333},{"speaker":"Casey","text":"Is that growth consistent across the quarter?","voice":"kokoro-v1-am_puck","audioUrl":"assets/dialogues/presenting-results-turn-3.mp3","sha256":"dbb653965b61932ed4668ca01d3048bfe707aa17aa9b77689ef6aa8a1f6b0233","bytes":20204,"seconds":2.426625},{"speaker":"Morgan","text":"Yes. The trend is positive across all three months, but I would like to highlight the increase in delivery costs.","voice":"kokoro-v1-af_nicole","audioUrl":"assets/dialogues/presenting-results-turn-4.mp3","sha256":"c8bf639c6179867a8fce4c90da30f474064572831e5db50b64f84c1058b3fe27","bytes":76268,"seconds":9.448666666666666},{"speaker":"Casey","text":"How did those costs affect the margin target?","voice":"kokoro-v1-am_puck","audioUrl":"assets/dialogues/presenting-results-turn-5.mp3","sha256":"bf851769684acefc5ee7ead64e91f296629d0cd40f6a289876fd9892bd79d424","bytes":20012,"seconds":2.4153333333333333},{"speaker":"Morgan","text":"There is a shortfall of two percentage points in our margin target.","voice":"kokoro-v1-af_nicole","audioUrl":"assets/dialogues/presenting-results-turn-6.mp3","sha256":"68160d734084a6e87c2e29332861d25d1f7cbef59c83d3434213a0be9bcb1683","bytes":45740,"seconds":5.621333333333333},{"speaker":"Casey","text":"What does the forecast suggest for next quarter?","voice":"kokoro-v1-am_puck","audioUrl":"assets/dialogues/presenting-results-turn-7.mp3","sha256":"96236594ffbdfde4ad4eba1b3f4c17716b2f2235d26ea132fa1ec97c1cee844d","bytes":20204,"seconds":2.438},{"speaker":"Morgan","text":"It suggests further growth, assuming demand remains stable. That is a forecast, not a guarantee.","voice":"kokoro-v1-af_nicole","audioUrl":"assets/dialogues/presenting-results-turn-8.mp3","sha256":"5ab133386fa31e5e086043031a1063b185199597cabc76705380d607e614fc97","bytes":77612,"seconds":9.600666666666667},{"speaker":"Casey","text":"What is your recommendation?","voice":"kokoro-v1-am_puck","audioUrl":"assets/dialogues/presenting-results-turn-9.mp3","sha256":"6fbfc7bcf785516b276604d65c5bc5a02648bd4c695ce7a041c9f9f165af3592","bytes":13292,"seconds":1.5693333333333332},{"speaker":"Morgan","text":"My recommendation is to review delivery routes and run a small pilot before expanding.","voice":"kokoro-v1-af_nicole","audioUrl":"assets/dialogues/presenting-results-turn-10.mp3","sha256":"2fd0cb10357da796adba73dd2dc8598bbe42b02ac3943a4af296d652924d942c","bytes":67436,"seconds":8.352},{"speaker":"Casey","text":"Agreed. Our next step is to assign a pilot owner and review costs in two weeks.","voice":"kokoro-v1-am_puck","audioUrl":"assets/dialogues/presenting-results-turn-11.mp3","sha256":"07415fe19bdd46ff2d09101b6e928080002cff5ba07f25c4f7ed8ca4a3d41252","bytes":40940,"seconds":5.018666666666666}],"email-request":[{"speaker":"Riley","text":"Before I send the email, does this subject line work: proposal review requested by Thursday?","voice":"kokoro-v1-af_sarah","audioUrl":"assets/dialogues/email-request-turn-0.mp3","sha256":"d3dd57e0f88966e5c80b25613af851cad0ecb7b4353797d6d8ebeb587f18876f","bytes":45548,"seconds":5.5986666666666665},{"speaker":"Jamie","text":"Yes. It is concise and tells the recipient what you need.","voice":"kokoro-v1-am_echo","audioUrl":"assets/dialogues/email-request-turn-1.mp3","sha256":"85a0171981bf4567f270e0a1ab2725d391dc43b10abcefc91e06e36f40778ee3","bytes":32876,"seconds":4.008666666666667},{"speaker":"Riley","text":"My request is for you to check the cost figures. The full proposal is in the attachment.","voice":"kokoro-v1-af_sarah","audioUrl":"assets/dialogues/email-request-turn-2.mp3","sha256":"032d3a47b2a9b69ab4166e2e10703a47fa91e7141d0b326ef6c5384f7ec1516d","bytes":43628,"seconds":5.365333333333333},{"speaker":"Jamie","text":"Please clarify which figures need checking. Do you mean the delivery costs?","voice":"kokoro-v1-am_echo","audioUrl":"assets/dialogues/email-request-turn-3.mp3","sha256":"c9d80a02e37ab8b856d1b9fca2e26ec624c60eb1f9eaa3559609ca05ec07d787","bytes":36140,"seconds":4.437333333333333},{"speaker":"Riley","text":"Exactly. The deadline for feedback is Thursday at noon because the client meeting is on Friday.","voice":"kokoro-v1-af_sarah","audioUrl":"assets/dialogues/email-request-turn-4.mp3","sha256":"802757e5953dd3ba1ff0361098d956f3eb20c956802e76cf1c20e495121098ea","bytes":45356,"seconds":5.588625},{"speaker":"Jamie","text":"I have availability on Wednesday afternoon. I can review those figures then.","voice":"kokoro-v1-am_echo","audioUrl":"assets/dialogues/email-request-turn-5.mp3","sha256":"dc724a271377977b88b0ad3278e6ef289742064d758d057cec17afa1d19cbff3","bytes":39020,"seconds":4.778666666666667},{"speaker":"Riley","text":"Great. Could you confirm that you received the proposal?","voice":"kokoro-v1-af_sarah","audioUrl":"assets/dialogues/email-request-turn-6.mp3","sha256":"46517adc00e560b423cfc0110c14b8abbf9d417b3688eb53d5fa42f2b4ba97a2","bytes":25580,"seconds":3.1173333333333333},{"speaker":"Jamie","text":"Yes. I can acknowledge receipt now, but that does not mean I have approved the figures yet.","voice":"kokoro-v1-am_echo","audioUrl":"assets/dialogues/email-request-turn-7.mp3","sha256":"d0b3e6c3b7f03e82c5548b6bafe021e76fba59c5a9fb5876f8c3198c5798c94b","bytes":42284,"seconds":5.203333333333333},{"speaker":"Riley","text":"Understood. I will send a brief follow-up on Thursday morning if I have not heard from you.","voice":"kokoro-v1-af_sarah","audioUrl":"assets/dialogues/email-request-turn-8.mp3","sha256":"e6d58d2cf0b025f55f634aa6e180984bc6fb88de13bb89facad87cf23527f56c","bytes":41324,"seconds":5.086666666666667},{"speaker":"Jamie","text":"That works. I will flag any questions during the review.","voice":"kokoro-v1-am_echo","audioUrl":"assets/dialogues/email-request-turn-9.mp3","sha256":"740863ffc0057bb7ef54debfd8124012facc8287327f2c406f66a10d82674bb8","bytes":28844,"seconds":3.525333333333333},{"speaker":"Riley","text":"Let us confirm the next steps: you review the delivery costs, and I update the proposal after your feedback.","voice":"kokoro-v1-af_sarah","audioUrl":"assets/dialogues/email-request-turn-10.mp3","sha256":"a104685be56c73d62593ecad6383ed3beb7d7f1f581ddfd990b989c7e3504400","bytes":50348,"seconds":6.196},{"speaker":"Jamie","text":"Agreed. I will reply with my comments by Thursday at noon.","voice":"kokoro-v1-am_echo","audioUrl":"assets/dialogues/email-request-turn-11.mp3","sha256":"e095bdcb84a172595c2d1fe69eb7f24e8555bcfe434e28aa3acadbc6e0ba7212","bytes":32300,"seconds":3.956}],"customer-recovery":[{"speaker":"Drew","text":"My delivery arrived damaged. I need to resolve this issue before I can use the product.","voice":"kokoro-v1-af_nova","audioUrl":"assets/dialogues/customer-recovery-turn-0.mp3","sha256":"2cae9920f36e84c9bb0b48ce2e387f10fbafa50201c814ee2f9b915d5fb10497","bytes":45164,"seconds":5.568},{"speaker":"Quinn","text":"I apologize for the inconvenience. Could you tell me what was damaged?","voice":"kokoro-v1-am_liam","audioUrl":"assets/dialogues/customer-recovery-turn-1.mp3","sha256":"d3b9f22011a0ef4ff63b839a49b6f657533a58e2e8cdf3839266ce3103fa2934","bytes":33260,"seconds":4.065333333333333},{"speaker":"Drew","text":"The outer box was crushed, and the product has a crack.","voice":"kokoro-v1-af_nova","audioUrl":"assets/dialogues/customer-recovery-turn-2.mp3","sha256":"fd0377ee151e217a56a2d9c36c4f42764c7fa7e7a58877f45adb4dbf6baf45b2","bytes":28844,"seconds":3.5273333333333334},{"speaker":"Quinn","text":"Thank you for explaining. We will investigate what happened. Could you send a photo and your order number?","voice":"kokoro-v1-am_liam","audioUrl":"assets/dialogues/customer-recovery-turn-3.mp3","sha256":"0ab05a4fcaa35bd901c7088f9ca39a5498f568b2dd106ea648b27498671c4aa4","bytes":46508,"seconds":5.714666666666667},{"speaker":"Drew","text":"Yes. What options will I have after you check the damage?","voice":"kokoro-v1-af_nova","audioUrl":"assets/dialogues/customer-recovery-turn-4.mp3","sha256":"5c14fe1a6a74c0fd35c0290a73bd8920bc2f9efedc499564293dc387b87fa8dd","bytes":28268,"seconds":3.4346666666666668},{"speaker":"Quinn","text":"For this order, we can offer a replacement or a refund after the damage is confirmed.","voice":"kokoro-v1-am_liam","audioUrl":"assets/dialogues/customer-recovery-turn-5.mp3","sha256":"a7d30f6735766938a0dfe825246b8af4dafb8dc2cac9c25d2067e105963b0d23","bytes":38636,"seconds":4.735291666666667},{"speaker":"Drew","text":"I would prefer a replacement, but I need a realistic expectation for the delivery time.","voice":"kokoro-v1-af_nova","audioUrl":"assets/dialogues/customer-recovery-turn-6.mp3","sha256":"fd483c1601f07a1e8f2fa68d48635428a079492bef2a1ee063500b2c04c8f573","bytes":42284,"seconds":5.205333333333333},{"speaker":"Quinn","text":"I cannot confirm the delivery date yet. This needs an escalation to our delivery team.","voice":"kokoro-v1-am_liam","audioUrl":"assets/dialogues/customer-recovery-turn-7.mp3","sha256":"a01dcb2f026900e44acd573d15ced52f4c13f417a19f1af9d3ea53a4bfffa703","bytes":41324,"seconds":5.088},{"speaker":"Drew","text":"When will I hear from you again?","voice":"kokoro-v1-af_nova","audioUrl":"assets/dialogues/customer-recovery-turn-8.mp3","sha256":"9e3092a9615e1b61415d8c8024a16edf96dddec230467fa9ad8512d9129a9365","bytes":19052,"seconds":2.2826666666666666},{"speaker":"Quinn","text":"I will send an update by noon tomorrow, even if the delivery date is still being checked.","voice":"kokoro-v1-am_liam","audioUrl":"assets/dialogues/customer-recovery-turn-9.mp3","sha256":"85b54df47c9a34a2eb00edd25e7350d6183de3fe7c0572b8c833e6aa3b10b7fe","bytes":39788,"seconds":4.874666666666666},{"speaker":"Drew","text":"That gives me some assurance. Please keep me informed.","voice":"kokoro-v1-af_nova","audioUrl":"assets/dialogues/customer-recovery-turn-10.mp3","sha256":"41e9bab8c46a20619a10336b221a26b617ea1e34b610da4479c370767c3cdc22","bytes":29420,"seconds":3.5872916666666668},{"speaker":"Quinn","text":"Of course. I will follow through: I will review your photo, contact the delivery team and send the update tomorrow.","voice":"kokoro-v1-am_liam","audioUrl":"assets/dialogues/customer-recovery-turn-11.mp3","sha256":"3ea6b24c675787be04b664584e07f5b5a56208384fdf210452ee9a92ba8d4ebe","bytes":49004,"seconds":6.026}],"interview-evidence":[{"speaker":"Avery","text":"Could you tell me about your background and experience?","voice":"kokoro-v1-af_kore","audioUrl":"assets/dialogues/interview-evidence-turn-0.mp3","sha256":"6e28b961fef0d7781d4c50f293f223796da919362aebee60047447307b684488","bytes":24044,"seconds":2.9226666666666667},{"speaker":"Robin","text":"My background is in customer support. I have three years of experience coordinating customer requests.","voice":"kokoro-v1-am_eric","audioUrl":"assets/dialogues/interview-evidence-turn-1.mp3","sha256":"c0d6a4acfa9a50665d6a5cbb3198689856f18799b89738272d0b6f9a6aad1813","bytes":46316,"seconds":5.708},{"speaker":"Avery","text":"What strength would help you contribute to this role?","voice":"kokoro-v1-af_kore","audioUrl":"assets/dialogues/interview-evidence-turn-2.mp3","sha256":"460f60341bcc40fc5d69795970070e1e6ad849fbc2fa496e21eb962d0b8b77d3","bytes":22124,"seconds":2.6652916666666666},{"speaker":"Robin","text":"My main strength is clear communication. I can contribute by making handoffs easier to understand.","voice":"kokoro-v1-am_eric","audioUrl":"assets/dialogues/interview-evidence-turn-3.mp3","sha256":"1452c8d0694c7b05b177c67d0d33ee1e72c605fef981d0ea854f6cab930942d1","bytes":44780,"seconds":5.497333333333334},{"speaker":"Avery","text":"Can you give a relevant example of a challenge you handled?","voice":"kokoro-v1-af_kore","audioUrl":"assets/dialogues/interview-evidence-turn-4.mp3","sha256":"cbe7f177d0c2ded220ccbdf2d49610bf3e4da88353b0fe31a24a26966a5ad52a","bytes":27500,"seconds":3.3493333333333335},{"speaker":"Robin","text":"I will use STAR: Situation, Task, Action, Result. We had a high volume of requests after a product launch.","voice":"kokoro-v1-am_eric","audioUrl":"assets/dialogues/interview-evidence-turn-5.mp3","sha256":"635ece5228c20c80a0f10e405c93d9cee7f8c28f5536b749dcb31b8224e4dae0","bytes":49580,"seconds":6.1066666666666665},{"speaker":"Avery","text":"What was your responsibility, and what action did you take?","voice":"kokoro-v1-af_kore","audioUrl":"assets/dialogues/interview-evidence-turn-6.mp3","sha256":"a6bdc7587df0d69827ff7b986809103772a851218ff8ba24e8beaa3c714ed7da","bytes":26732,"seconds":3.2613333333333334},{"speaker":"Robin","text":"My responsibility was to coordinate the response. I created a shared priority list and clarified the owner of each request.","voice":"kokoro-v1-am_eric","audioUrl":"assets/dialogues/interview-evidence-turn-7.mp3","sha256":"203c789024386ccb82d00d5e564cc932ed3cfd11bfb28d929851e90972ba46bc","bytes":57260,"seconds":7.073333333333333},{"speaker":"Avery","text":"What was the achievement? Was the result measurable?","voice":"kokoro-v1-af_kore","audioUrl":"assets/dialogues/interview-evidence-turn-8.mp3","sha256":"80fef5fed5bd47379eeb8cabb6cfdc450b1284aab030e52a6bc10f31644d6bb2","bytes":24236,"seconds":2.942},{"speaker":"Robin","text":"Our average response time fell from two days to one day. Teamwork made that possible; I coordinated the process, and colleagues handled the individual cases.","voice":"kokoro-v1-am_eric","audioUrl":"assets/dialogues/interview-evidence-turn-9.mp3","sha256":"d04a9402b50faa98295b24168e31160a53637f72915e8138bc4e79b21de5ecd7","bytes":69356,"seconds":8.57},{"speaker":"Avery","text":"Which skill would you like to improve next?","voice":"kokoro-v1-af_kore","audioUrl":"assets/dialogues/interview-evidence-turn-10.mp3","sha256":"8a7eee347ef7ce1f29e4ffd0072ab99c0cd9079b8e121d423cbd801b560de501","bytes":17324,"seconds":2.076625},{"speaker":"Robin","text":"I want to improve my presentation skills. I am practising short updates and asking colleagues for feedback.","voice":"kokoro-v1-am_eric","audioUrl":"assets/dialogues/interview-evidence-turn-11.mp3","sha256":"50d160d7453fa2af5c1bbd723f53a9e81e18a745f6bba5cc7d619bac70f655e2","bytes":47276,"seconds":5.8272916666666665}],"workplace-introductions":[{"speaker":"Lee","text":"Hello, I am Lee, your new colleague. Welcome!","voice":"kokoro-v1-af_jessica","audioUrl":"assets/dialogues/workplace-introductions-turn-0.mp3","sha256":"7f907f68ecd89f4aa658fffba8e901c218a738d281cc399cd6c641b9814a5e42","bytes":19628,"seconds":2.3526666666666665},{"speaker":"Sam","text":"Hi, Lee. I am Sam. It is nice to meet you.","voice":"kokoro-v1-af_bella","audioUrl":"assets/dialogues/workplace-introductions-turn-1.mp3","sha256":"12f60fd3658acdcb3d4f4d74a0773569965153aa9c8dccfb296e2b2f67a9037c","bytes":25004,"seconds":3.0379583333333335},{"speaker":"Lee","text":"Nice to meet you too. Which department do you work in?","voice":"kokoro-v1-af_jessica","audioUrl":"assets/dialogues/workplace-introductions-turn-2.mp3","sha256":"03382e189e823b0b026c4564044ff3a7f05d0fba93e714d87a4f583cae74951e","bytes":23852,"seconds":2.8986666666666667},{"speaker":"Sam","text":"I work in support. My role is to help customers with their orders.","voice":"kokoro-v1-af_bella","audioUrl":"assets/dialogues/workplace-introductions-turn-3.mp3","sha256":"74d7e01f9c15e3500c802035e257a23e81be0813d4c5baa94a62a65eed269c36","bytes":34988,"seconds":4.286},{"speaker":"Lee","text":"What are you responsible for on the team?","voice":"kokoro-v1-af_jessica","audioUrl":"assets/dialogues/workplace-introductions-turn-4.mp3","sha256":"94e14051cc558f159a5a81fbd953e4a60dac0de1b88c4c0c6d9a3dd909484d35","bytes":19436,"seconds":2.33},{"speaker":"Sam","text":"I am responsible for customer messages. I work with the delivery team too.","voice":"kokoro-v1-af_bella","audioUrl":"assets/dialogues/workplace-introductions-turn-5.mp3","sha256":"2d5899e7c21fa59438f738c44199fe3b960b35e38fec7aa54099cb4d0d26a8a9","bytes":37484,"seconds":4.606},{"speaker":"Lee","text":"Is your team based in Recife?","voice":"kokoro-v1-af_jessica","audioUrl":"assets/dialogues/workplace-introductions-turn-6.mp3","sha256":"dabc35712f8ea33c87ebbd65603a58d7cb677b03425fb6c3db1c4a807e07ab6e","bytes":17324,"seconds":2.0813333333333333},{"speaker":"Sam","text":"Yes. I will join their daily meeting tomorrow. What do you do?","voice":"kokoro-v1-af_bella","audioUrl":"assets/dialogues/workplace-introductions-turn-7.mp3","sha256":"377c0810e0a1d7a77a8af1236e6009ca395bac6d1e1336bb3a765f2c048a14fd","bytes":29804,"seconds":3.630625},{"speaker":"Lee","text":"I work in sales. Sometimes a customer asks me about an order.","voice":"kokoro-v1-af_jessica","audioUrl":"assets/dialogues/workplace-introductions-turn-8.mp3","sha256":"03668feb263ab49994d54c0929e4ff13388b7e9e031c61c5f964afe571e9965d","bytes":29804,"seconds":3.648},{"speaker":"Sam","text":"You can contact me by email. I can explain our support process.","voice":"kokoro-v1-af_bella","audioUrl":"assets/dialogues/workplace-introductions-turn-9.mp3","sha256":"1ea0d9912a4d8d13734dd4702156a8eff45c0901734e5b1aadbce572e2297322","bytes":32684,"seconds":3.998666666666667},{"speaker":"Lee","text":"Thank you. Are you available after lunch for a short conversation?","voice":"kokoro-v1-af_jessica","audioUrl":"assets/dialogues/workplace-introductions-turn-10.mp3","sha256":"2e88cf592ded520547ecb28558d9d3ea42332e053a67170ba08900fc645491c5","bytes":29228,"seconds":3.5713333333333335},{"speaker":"Sam","text":"Yes, at two. I will send you a meeting invitation. See you then.","voice":"kokoro-v1-af_bella","audioUrl":"assets/dialogues/workplace-introductions-turn-11.mp3","sha256":"9de93130da1a240f8de7066c4ef4220c854fadd21c62d721da6ec2e2243b0340","bytes":33644,"seconds":4.109916666666667}],"scheduling-a-meeting":[{"speaker":"Casey","text":"Hi, Noor. Are you free on Tuesday for a short meeting about the draft report?","voice":"kokoro-v1-am_puck","audioUrl":"assets/dialogues/scheduling-a-meeting-turn-0.mp3","sha256":"dcaa66770e14af156b18cc94e1a57795ce78dd59b72e642402ebd793d66b88e6","bytes":36140,"seconds":4.436625},{"speaker":"Noor","text":"Let me check my schedule. What time would you like to meet?","voice":"kokoro-v1-am_onyx","audioUrl":"assets/dialogues/scheduling-a-meeting-turn-1.mp3","sha256":"79dd4bb5a5afe604f6d802d76b09b04de55e8160391216719197e9079bb0afc1","bytes":29036,"seconds":3.550666666666667},{"speaker":"Casey","text":"Would ten in the morning work for you?","voice":"kokoro-v1-am_puck","audioUrl":"assets/dialogues/scheduling-a-meeting-turn-2.mp3","sha256":"3860bb48eab4bd6d8037fdaf834304a68bc2c009f6093f62dd8f97f1b8990299","bytes":14828,"seconds":1.7626666666666666},{"speaker":"Noor","text":"I am busy at ten. Could we meet at eleven instead?","voice":"kokoro-v1-am_onyx","audioUrl":"assets/dialogues/scheduling-a-meeting-turn-3.mp3","sha256":"705f518c264513d5e796287fc5ed06967221ee183f22a6859a38472d6e9e6867","bytes":31916,"seconds":3.9053333333333335},{"speaker":"Casey","text":"Yes. Does eleven suit you for an online meeting?","voice":"kokoro-v1-am_puck","audioUrl":"assets/dialogues/scheduling-a-meeting-turn-4.mp3","sha256":"6d57464d8162e289c116d3bb295245b22b266d0db547ed73d7523168c70c78a2","bytes":22700,"seconds":2.743333333333333},{"speaker":"Noor","text":"Yes. Which time zone are we using?","voice":"kokoro-v1-am_onyx","audioUrl":"assets/dialogues/scheduling-a-meeting-turn-5.mp3","sha256":"755a2942959a6d4c7578a88628a9e31058a25d0e7c1b34bd6590fd1da38c8426","bytes":22508,"seconds":2.712625},{"speaker":"Casey","text":"Brasília time. The meeting will last twenty minutes.","voice":"kokoro-v1-am_puck","audioUrl":"assets/dialogues/scheduling-a-meeting-turn-6.mp3","sha256":"7393676dd0e31a6ba715834721ff8a9ccfd0e868c8cea67585c3424b2068048d","bytes":23276,"seconds":2.810625},{"speaker":"Noor","text":"That works. Could you confirm the details by email?","voice":"kokoro-v1-am_onyx","audioUrl":"assets/dialogues/scheduling-a-meeting-turn-7.mp3","sha256":"440c2c3dc353449359ec861050361c1f4cf3965aa83bb33b10847f66198833af","bytes":29996,"seconds":3.6653333333333333},{"speaker":"Casey","text":"Of course. I will send an invitation with the meeting link today.","voice":"kokoro-v1-am_puck","audioUrl":"assets/dialogues/scheduling-a-meeting-turn-8.mp3","sha256":"589feaa2e8cd401047c765883140f23cfedcb49a2187330fb72d11d269549ece","bytes":27500,"seconds":3.347958333333333},{"speaker":"Noor","text":"Thank you. Please tell me if we need to reschedule.","voice":"kokoro-v1-am_onyx","audioUrl":"assets/dialogues/scheduling-a-meeting-turn-9.mp3","sha256":"387a232817f6f03ef8eecb893a0b492bfcbb7f2d4b9732b90e02404dc2f590da","bytes":28652,"seconds":3.4846666666666666},{"speaker":"Casey","text":"I will. So, Tuesday at eleven, Brasília time, for twenty minutes.","voice":"kokoro-v1-am_puck","audioUrl":"assets/dialogues/scheduling-a-meeting-turn-10.mp3","sha256":"ea92c5ffa39ea4de3b817f784586cab5494bf3b29b2ce41dae6bc740a1633949","bytes":31724,"seconds":3.876},{"speaker":"Noor","text":"Confirmed. I look forward to our conversation about the draft.","voice":"kokoro-v1-am_onyx","audioUrl":"assets/dialogues/scheduling-a-meeting-turn-11.mp3","sha256":"5c16ea42a25794dc2a3188aec29e9327f26bf97690e295853e8000892dfaa415","bytes":31724,"seconds":3.8806666666666665}],"taking-a-phone-message":[{"speaker":"Dana","text":"Good morning. Thank you for calling North Office. How can I help?","voice":"kokoro-v1-af_river","audioUrl":"assets/dialogues/taking-a-phone-message-turn-0.mp3","sha256":"1e94d4d78df9cbea51ce8ded4c4251e4abd1a5fe1f29a0fe925c890679ed86dd","bytes":30764,"seconds":3.7459583333333333},{"speaker":"Pat","text":"Hello. May I speak to Mr Chen, please?","voice":"kokoro-v1-am_adam","audioUrl":"assets/dialogues/taking-a-phone-message-turn-1.mp3","sha256":"3e0e7af44fdbf697ecc13dc05f4158799f6842014f1d63e811c808a7be7752b1","bytes":19052,"seconds":2.296666666666667},{"speaker":"Dana","text":"Could you hold for a moment while I check?","voice":"kokoro-v1-af_river","audioUrl":"assets/dialogues/taking-a-phone-message-turn-2.mp3","sha256":"1ce65b7e76f45db7c0e297299a68fc5541789c88189c169f5da1d6a92c88312d","bytes":18668,"seconds":2.24},{"speaker":"Pat","text":"Of course. My name is Pat Vale from the delivery team.","voice":"kokoro-v1-am_adam","audioUrl":"assets/dialogues/taking-a-phone-message-turn-3.mp3","sha256":"898ccc94de149f4252a35a03d88e665f443a1c496860ec3e5999ea66813f899e","bytes":26924,"seconds":3.2739583333333333},{"speaker":"Dana","text":"He is in a meeting. May I take a message?","voice":"kokoro-v1-af_river","audioUrl":"assets/dialogues/taking-a-phone-message-turn-4.mp3","sha256":"88e0be6ad05ec86bc656f2b7c71afc97b58549773776e10adc038655bc700a96","bytes":20012,"seconds":2.4106666666666667},{"speaker":"Pat","text":"Yes. Could he call back about order seven six when he is free?","voice":"kokoro-v1-am_adam","audioUrl":"assets/dialogues/taking-a-phone-message-turn-5.mp3","sha256":"6ea9f8d3cc3315f87e7b558cef9358c369ddc96b0ac0d81997742fd785971e07","bytes":27308,"seconds":3.3252916666666668},{"speaker":"Dana","text":"Certainly. Could you spell your surname and tell me how he can reach you?","voice":"kokoro-v1-af_river","audioUrl":"assets/dialogues/taking-a-phone-message-turn-6.mp3","sha256":"7984bba37fe1fc086293a67a167138e4cc765d6cf42972c6411bfafb3fbd8a39","bytes":29036,"seconds":3.5393333333333334},{"speaker":"Pat","text":"Vale: V-A-L-E. He has the team number. My extension is four two.","voice":"kokoro-v1-am_adam","audioUrl":"assets/dialogues/taking-a-phone-message-turn-7.mp3","sha256":"428a306243171535d5f7af5750c043d289a6e1707b2831926aa6eae02843bd51","bytes":32108,"seconds":3.9133333333333336},{"speaker":"Dana","text":"Could you repeat the extension? Is the request urgent?","voice":"kokoro-v1-af_river","audioUrl":"assets/dialogues/taking-a-phone-message-turn-8.mp3","sha256":"235a647bbe8ae7b556b1ed089bf933e57a8069da7437681e681529847cc38d5b","bytes":25580,"seconds":3.1146666666666665},{"speaker":"Pat","text":"Four two. It is not urgent. I want to confirm the delivery day.","voice":"kokoro-v1-am_adam","audioUrl":"assets/dialogues/taking-a-phone-message-turn-9.mp3","sha256":"a27add0f7bba80ee9b2fdf19d466345c0bd81ad124beee81d396996d5afad273","bytes":33836,"seconds":4.144666666666667},{"speaker":"Dana","text":"Let me read back the message: Pat Vale, extension four two, order seven six, to confirm the delivery day. I will pass on your message when the meeting ends.","voice":"kokoro-v1-af_river","audioUrl":"assets/dialogues/taking-a-phone-message-turn-10.mp3","sha256":"84be2c88d9faadb51dc6c76f039a2d16374c869000cd4c2a8e3f8bf54313d71b","bytes":65708,"seconds":8.13},{"speaker":"Pat","text":"That is correct. Thank you for your help. Goodbye.","voice":"kokoro-v1-am_adam","audioUrl":"assets/dialogues/taking-a-phone-message-turn-11.mp3","sha256":"ab5ea0b190805a48425f568d6cd387c89ab91a17d91041fcc3cc8503a5d422fa","bytes":23276,"seconds":2.8213333333333335}],"clarify-and-confirm":[{"speaker":"Casey","text":"Could you prepare the client file? Please use the latest version.","voice":"kokoro-v1-am_puck","audioUrl":"assets/dialogues/clarify-and-confirm-turn-0.mp3","sha256":"05b343381a7638cb3895bac6d76c61603492fb845d635a3ddda0c84da0b0d77f","bytes":29420,"seconds":3.5879583333333334},{"speaker":"Morgan","text":"I need some clarification. Which file does that refer to?","voice":"kokoro-v1-af_nicole","audioUrl":"assets/dialogues/clarify-and-confirm-turn-1.mp3","sha256":"7ddc5858290fb78f250618763fa2294a6081461b4362cbff3b216768ca5c2b70","bytes":41516,"seconds":5.097958333333334},{"speaker":"Casey","text":"The sales summary in the attachment I sent this morning.","voice":"kokoro-v1-am_puck","audioUrl":"assets/dialogues/clarify-and-confirm-turn-2.mp3","sha256":"56b7173346084d5171436bffc7c9b7f40c8ea4d5b0a507fd5bed5b96e07d792c","bytes":24812,"seconds":3.0152916666666667},{"speaker":"Morgan","text":"Could you be more specific about the figures you need?","voice":"kokoro-v1-af_nicole","audioUrl":"assets/dialogues/clarify-and-confirm-turn-3.mp3","sha256":"a7d4413acb7b023381362ee0e8f693408690d41b7e2dd3c9126314b7362ebda8","bytes":32492,"seconds":3.9672916666666667},{"speaker":"Casey","text":"Please include the total for June and the comparison with May.","voice":"kokoro-v1-am_puck","audioUrl":"assets/dialogues/clarify-and-confirm-turn-4.mp3","sha256":"a97d9b9290e7fe2bcf82ecdea6e1b9652dddd85887cc0273b2cdb547bbe902d2","bytes":28652,"seconds":3.4972916666666665},{"speaker":"Morgan","text":"Should I leave out the regional detail?","voice":"kokoro-v1-af_nicole","audioUrl":"assets/dialogues/clarify-and-confirm-turn-5.mp3","sha256":"949c3aace7629338a0b8e1c0ffa2e158b72ee0aa312a02ced414b57dc3ac5075","bytes":22316,"seconds":2.6973333333333334},{"speaker":"Casey","text":"Yes. The agreed scope is one page for the client call.","voice":"kokoro-v1-am_puck","audioUrl":"assets/dialogues/clarify-and-confirm-turn-6.mp3","sha256":"1df5ac1699e268435cc89b5f2eebbe6aa30def6a707c0cd2ae1e7cd6e942afe3","bytes":26924,"seconds":3.2879583333333335},{"speaker":"Morgan","text":"In other words, you need the total and a monthly comparison, without regional figures.","voice":"kokoro-v1-af_nicole","audioUrl":"assets/dialogues/clarify-and-confirm-turn-7.mp3","sha256":"15e44fd6d9923352fa80c83e3cd788ae02714c550e5dd3c8d6137473ede12324","bytes":63788,"seconds":7.891333333333334},{"speaker":"Casey","text":"Exactly. Could you send it by noon tomorrow?","voice":"kokoro-v1-am_puck","audioUrl":"assets/dialogues/clarify-and-confirm-turn-8.mp3","sha256":"43bdfb70ad0f7b6a274051a71f9703f8d33a5fdd885ec55263c638060de361a3","bytes":20012,"seconds":2.404},{"speaker":"Morgan","text":"Let me check my understanding: I prepare one page and send it to you by noon tomorrow.","voice":"kokoro-v1-af_nicole","audioUrl":"assets/dialogues/clarify-and-confirm-turn-9.mp3","sha256":"b114fdcc4d6a5409ce67471459a3152ccc0115b88f67634c4325c9b15be0bb07","bytes":60140,"seconds":7.433333333333334},{"speaker":"Casey","text":"Correct. I will review it before the client call.","voice":"kokoro-v1-am_puck","audioUrl":"assets/dialogues/clarify-and-confirm-turn-10.mp3","sha256":"86662bb53c5d6ede7c60b127010ff3420d42d23b65c0ef73d9d8ed4086bdfbaf","bytes":22508,"seconds":2.719333333333333},{"speaker":"Morgan","text":"Thank you. I will confirm in writing so we both have the same instructions.","voice":"kokoro-v1-af_nicole","audioUrl":"assets/dialogues/clarify-and-confirm-turn-11.mp3","sha256":"9dbc99d2875209e667a1501f0d12046bef98bc890d7e2821821e30666b90abf7","bytes":51308,"seconds":6.312666666666667}],"concise-project-update":[{"speaker":"Riley","text":"The main takeaway is that our portal pilot reduced response time.","voice":"kokoro-v1-af_sarah","audioUrl":"assets/dialogues/concise-project-update-turn-0.mp3","sha256":"1ade2654ff4b42c4f2f2e3cce94d136ec21ba881cc09cbfabbe48df936a7cd2a","bytes":31916,"seconds":3.892},{"speaker":"Jamie","text":"What was the baseline?","voice":"kokoro-v1-am_echo","audioUrl":"assets/dialogues/concise-project-update-turn-1.mp3","sha256":"18feb1a95f4554284402c6a7cf1b47d8e596ee79c7a8c10662b623042fdc1e61","bytes":14636,"seconds":1.7493333333333334},{"speaker":"Riley","text":"Five hours in May. In June, the average was three hours compared with five before the pilot.","voice":"kokoro-v1-af_sarah","audioUrl":"assets/dialogues/concise-project-update-turn-2.mp3","sha256":"0c44b4f02d5325427f0d002f60a8e7e87df8e749da9ccc7362ff747dee7cc619","bytes":47276,"seconds":5.8133333333333335},{"speaker":"Jamie","text":"How large was the sample?","voice":"kokoro-v1-am_echo","audioUrl":"assets/dialogues/concise-project-update-turn-3.mp3","sha256":"33462e84a7de7a19dfb7f73de751c0dc9c3de7e526162595418b38db39686fd8","bytes":17132,"seconds":2.048},{"speaker":"Riley","text":"Twenty requests from one team. That result is encouraging, but it has a limitation.","voice":"kokoro-v1-af_sarah","audioUrl":"assets/dialogues/concise-project-update-turn-4.mp3","sha256":"aa692776a9e97859691a606d177809126e69b072e342694d5516a721e92a80a5","bytes":43244,"seconds":5.3112916666666665},{"speaker":"Jamie","text":"You mean we cannot assume every team will get the same improvement?","voice":"kokoro-v1-am_echo","audioUrl":"assets/dialogues/concise-project-update-turn-5.mp3","sha256":"6c62818b15062d5b6b30a76efed35c0684b0fa2fd4c3d3923e8021b4f1bff5c1","bytes":32108,"seconds":3.925333333333333},{"speaker":"Riley","text":"Exactly. A wider rollout would be a forecast, not a measured result.","voice":"kokoro-v1-af_sarah","audioUrl":"assets/dialogues/concise-project-update-turn-6.mp3","sha256":"acf72c4d84cb24a754cbedac987d4baf2529e8ca9754cefbe58a9a843c9e74f6","bytes":34796,"seconds":4.254666666666667},{"speaker":"Jamie","text":"What is the main risk if we expand now?","voice":"kokoro-v1-am_echo","audioUrl":"assets/dialogues/concise-project-update-turn-7.mp3","sha256":"b88f3fb11be80121c181a8483ff86dd411feec0ec68b70a45977ddbf257fc616","bytes":23276,"seconds":2.816},{"speaker":"Riley","text":"Support capacity. My recommendation is a second two-week test with another team.","voice":"kokoro-v1-af_sarah","audioUrl":"assets/dialogues/concise-project-update-turn-8.mp3","sha256":"fdb67d2248d38f673b3ee7b1f01f17bdadc798cf08e6ff318595d6e66baf1135","bytes":42668,"seconds":5.236},{"speaker":"Jamie","text":"What approval do you need today?","voice":"kokoro-v1-am_echo","audioUrl":"assets/dialogues/concise-project-update-turn-9.mp3","sha256":"9b2c455a951bc10b134831df556b212b820cb98510e1eeeaf6d599b5d7b0148f","bytes":19052,"seconds":2.2826666666666666},{"speaker":"Riley","text":"Approval for that test. The next step is to confirm support availability before choosing a start date.","voice":"kokoro-v1-af_sarah","audioUrl":"assets/dialogues/concise-project-update-turn-10.mp3","sha256":"edb2900ba92a6a38f8fd4b9057ada38f5b56368dd626b828c24499c7074fa24a","bytes":48428,"seconds":5.972625},{"speaker":"Jamie","text":"Approved for planning. Please confirm capacity before you promise a launch date.","voice":"kokoro-v1-am_echo","audioUrl":"assets/dialogues/concise-project-update-turn-11.mp3","sha256":"6dd8da427a727835940262675e6bbf3839e1bb8d5b764ef6816e8d1fa6a1fa28","bytes":40172,"seconds":4.928}],"handover-across-teams":[{"speaker":"Drew","text":"Thanks for joining this handover. The background is a supplier review due on Friday.","voice":"kokoro-v1-af_nova","audioUrl":"assets/dialogues/handover-across-teams-turn-0.mp3","sha256":"922bfb6a6b98f7f35825c9fa9b7c10a904403f0a924bfbfb7dcdfdb814207cd2","bytes":41132,"seconds":5.054625},{"speaker":"Robin","text":"Which parts are completed?","voice":"kokoro-v1-am_eric","audioUrl":"assets/dialogues/handover-across-teams-turn-1.mp3","sha256":"30559f2ac6abdd1f4076c26bcfe07bf7fadee742d909a37ce2a043bbeb5c2fd0","bytes":13868,"seconds":1.6513333333333333},{"speaker":"Drew","text":"The contact details are completed. Final approval is pending, and legal approval is our dependency.","voice":"kokoro-v1-af_nova","audioUrl":"assets/dialogues/handover-across-teams-turn-2.mp3","sha256":"f94b0518cd6182e78006abb48ebeb43e320d8beb65ee9800e78677e1083b7829","bytes":52076,"seconds":6.424},{"speaker":"Robin","text":"Who is the point of contact for that approval?","voice":"kokoro-v1-am_eric","audioUrl":"assets/dialogues/handover-across-teams-turn-3.mp3","sha256":"4609795846779443b4943d0f8fdc8b8dfd8ccfd3ea49c8655586adfbb0ad8980","bytes":20780,"seconds":2.517333333333333},{"speaker":"Drew","text":"Lee in Legal. Do you have access to the shared folder and the checklist?","voice":"kokoro-v1-af_nova","audioUrl":"assets/dialogues/handover-across-teams-turn-4.mp3","sha256":"3d6f5622df32730e21c522c2870bbb2ab9041f89a58e14e950f6d3a7019c8325","bytes":34412,"seconds":4.212},{"speaker":"Robin","text":"Yes, I can open both. Please confirm your availability while you are away.","voice":"kokoro-v1-am_eric","audioUrl":"assets/dialogues/handover-across-teams-turn-5.mp3","sha256":"aa887b9fbc8622393361123ea4849aadb4747aaae486bc6c4bb65e39a1b24cc5","bytes":32684,"seconds":3.9953333333333334},{"speaker":"Drew","text":"I will be offline. If approval has not arrived by Thursday morning, escalate the issue to Lee.","voice":"kokoro-v1-af_nova","audioUrl":"assets/dialogues/handover-across-teams-turn-6.mp3","sha256":"ccda2d971dd8691657dbf2d9cf1b4da9afbe03659585a5cafe1b300162383d59","bytes":46508,"seconds":5.718},{"speaker":"Robin","text":"Should I send the supplier an approval message before Legal replies?","voice":"kokoro-v1-am_eric","audioUrl":"assets/dialogues/handover-across-teams-turn-7.mp3","sha256":"a2279a7d2e088c7d6e2dc041950b35f3784861b4235e0b61bbac5c7f1c1c2f26","bytes":30380,"seconds":3.7006666666666668},{"speaker":"Drew","text":"No. Follow the checklist and wait for approval. Please send me a status update on Thursday.","voice":"kokoro-v1-af_nova","audioUrl":"assets/dialogues/handover-across-teams-turn-8.mp3","sha256":"3a301220228b442318ac5ccd47d811d8a4c07742dc90a7009b3a4fb31318c2d6","bytes":45164,"seconds":5.556},{"speaker":"Robin","text":"I acknowledge the handover. I will check the folder, contact Lee if needed, and report the status.","voice":"kokoro-v1-am_eric","audioUrl":"assets/dialogues/handover-across-teams-turn-9.mp3","sha256":"18fa634378fbf7928d396e5f32f37e6d77e7ee1e6b33e1497dfc57c2b5cde455","bytes":41132,"seconds":5.047958333333334},{"speaker":"Drew","text":"Thank you. Please record the decision in the folder so the team can see it.","voice":"kokoro-v1-af_nova","audioUrl":"assets/dialogues/handover-across-teams-turn-10.mp3","sha256":"3533f5e7c57e72a8d469566bca1f8c6d2b65fa8f93f6f9615d5fa8d679112b33","bytes":34988,"seconds":4.288666666666667},{"speaker":"Robin","text":"Understood. I will not tell the supplier it is approved while the decision is still pending.","voice":"kokoro-v1-am_eric","audioUrl":"assets/dialogues/handover-across-teams-turn-11.mp3","sha256":"d7b8242aeb2acd2fb6fe190511709c7e938ef4f0b9f6b784acdb66fda59221ae","bytes":38636,"seconds":4.748}],"idioms-to-clear-actions":[{"speaker":"Morgan","text":"We can get the ball rolling with a short update. Welcome to the project, Riley.","voice":"kokoro-v1-af_nicole","audioUrl":"assets/dialogues/idioms-to-clear-actions-turn-0.mp3","sha256":"33fde3482e7d425b286f94a94ecdf395ec6fb8a17626ba599151549d5c2e009a","bytes":57836,"seconds":7.147333333333333},{"speaker":"Riley","text":"Thanks. Could you fill me in on the decision from yesterday?","voice":"kokoro-v1-af_sarah","audioUrl":"assets/dialogues/idioms-to-clear-actions-turn-1.mp3","sha256":"b543db011e8f59e815e4a196c38579ed4652b4f67fc3b525674a4478b55a4a30","bytes":26156,"seconds":3.171291666666667},{"speaker":"Morgan","text":"We agreed to draft a one-page summary. Tomorrow’s call starts at nine sharp, London time.","voice":"kokoro-v1-af_nicole","audioUrl":"assets/dialogues/idioms-to-clear-actions-turn-2.mp3","sha256":"5f329513fdf820c5d1eff0bb8e4827dfa3cf27923292d579800027b39bcfe7ce","bytes":68588,"seconds":8.478666666666667},{"speaker":"Riley","text":"Understood. Can we touch base on Wednesday to check the response?","voice":"kokoro-v1-af_sarah","audioUrl":"assets/dialogues/idioms-to-clear-actions-turn-3.mp3","sha256":"1ecd8f6fed90607d34107d17c46518e397049c348dad13fe6eee14ad8cff3804","bytes":31148,"seconds":3.796625},{"speaker":"Morgan","text":"Yes. First, let us check that we are on the same page about the summary.","voice":"kokoro-v1-af_nicole","audioUrl":"assets/dialogues/idioms-to-clear-actions-turn-4.mp3","sha256":"fffe8a91e59eafe7e889f2e639d1bb445d3de56aabc2c3ff786ddf2c4908c7c1","bytes":48812,"seconds":6.012666666666667},{"speaker":"Riley","text":"I can take the lead on the first draft and send it today.","voice":"kokoro-v1-af_sarah","audioUrl":"assets/dialogues/idioms-to-clear-actions-turn-5.mp3","sha256":"debadcfdffb79def0bf3511e169063d8dbf3deec0f32a1fec8b42b0a98a78ce0","bytes":24812,"seconds":3.018666666666667},{"speaker":"Morgan","text":"Great. Please keep me posted if any information is missing.","voice":"kokoro-v1-af_nicole","audioUrl":"assets/dialogues/idioms-to-clear-actions-turn-6.mp3","sha256":"247f873ea96e901576edb08fb9179ff85918f973b389dafbafd717de0112f420","bytes":40748,"seconds":5.004},{"speaker":"Riley","text":"I will put it in writing so the team can check the owner and deadline.","voice":"kokoro-v1-af_sarah","audioUrl":"assets/dialogues/idioms-to-clear-actions-turn-7.mp3","sha256":"7453bf4ae4bb30a2298575a01062705e7a8775e79343e17322b61ee1ec93c6d3","bytes":29996,"seconds":3.6573333333333333},{"speaker":"Morgan","text":"Please use plain English. Some colleagues are new to this project.","voice":"kokoro-v1-af_nicole","audioUrl":"assets/dialogues/idioms-to-clear-actions-turn-8.mp3","sha256":"0b71a9560449b226d92564c6028d48c650f7a52f045d4e633638a3b5d2e5164c","bytes":46508,"seconds":5.715333333333334},{"speaker":"Riley","text":"Of course. If an idiom causes confusion, I will explain it another way.","voice":"kokoro-v1-af_sarah","audioUrl":"assets/dialogues/idioms-to-clear-actions-turn-9.mp3","sha256":"e61b9bd42a3022e5f3ba948338bed8c0efebf6fb50a0cecc88f52ffd3c10014a","bytes":36716,"seconds":4.489333333333334},{"speaker":"Morgan","text":"Our next step is your draft today, followed by my review tomorrow.","voice":"kokoro-v1-af_nicole","audioUrl":"assets/dialogues/idioms-to-clear-actions-turn-10.mp3","sha256":"a27351f18a50e65ac8b457b95ba5bb545716ade225bc43785f9ea297758131d6","bytes":46700,"seconds":5.759291666666667},{"speaker":"Riley","text":"Then we can get the show on the road after your approval. I will send the summary today.","voice":"kokoro-v1-af_sarah","audioUrl":"assets/dialogues/idioms-to-clear-actions-turn-11.mp3","sha256":"4893dd483fd05dd34c008c176a378e8cdd64d98010b0b8abbb8771d48a920c3f","bytes":37676,"seconds":4.628625}],"budget-and-workflow":[{"speaker":"Dana","text":"Let us review the pilot budget. It is still a draft, so no new spending is approved.","voice":"kokoro-v1-af_river","audioUrl":"assets/dialogues/budget-and-workflow-turn-0.mp3","sha256":"3788f554958182393e8150a1840b2c7b6c2d4fca7e094fbebc9b749d911a8339","bytes":39020,"seconds":4.794666666666667},{"speaker":"Sam","text":"The spreadsheet separates last month’s results from next month’s estimates.","voice":"kokoro-v1-af_bella","audioUrl":"assets/dialogues/budget-and-workflow-turn-1.mp3","sha256":"41a53db6b8d637cb6e1403d52e9824ef70902d9aed81aae829892ecccbe33ad5","bytes":35180,"seconds":4.303958333333333},{"speaker":"Dana","text":"What revenue did the pilot generate last month?","voice":"kokoro-v1-af_river","audioUrl":"assets/dialogues/budget-and-workflow-turn-2.mp3","sha256":"666cd0a239bd5f69147fdbec9d814e7f5f9b850e35c896483669e18dafa98d7f","bytes":22892,"seconds":2.7733333333333334},{"speaker":"Sam","text":"Revenue was twenty thousand dollars, and profit was three thousand after recorded costs.","voice":"kokoro-v1-af_bella","audioUrl":"assets/dialogues/budget-and-workflow-turn-3.mp3","sha256":"89a203fbfd8836b5beed23bda008d37c7cd8c5f2534e77c251d7354432053e37","bytes":44396,"seconds":5.459333333333333},{"speaker":"Dana","text":"That does not tell us when customers pay. What does the cash flow forecast show?","voice":"kokoro-v1-af_river","audioUrl":"assets/dialogues/budget-and-workflow-turn-4.mp3","sha256":"cb913747c76263987410d3ddfd807610a901d4c616e65d24a29d9d3a64740c07","bytes":35756,"seconds":4.370666666666667},{"speaker":"Sam","text":"Some payments are expected next month. The cash flow forecast keeps that timing visible.","voice":"kokoro-v1-af_bella","audioUrl":"assets/dialogues/budget-and-workflow-turn-5.mp3","sha256":"71d7de028c9acf7a6d3b78411eb4d2cc3d0f235be10fc9dd82335b1b06f6ab98","bytes":44972,"seconds":5.524625},{"speaker":"Dana","text":"Our delivery KPI was ninety percent on time. The target is ninety-five percent.","voice":"kokoro-v1-af_river","audioUrl":"assets/dialogues/budget-and-workflow-turn-6.mp3","sha256":"f550f522377fdc713cf403f6cc326166afb9bfcb899b39e41f82d6758f675a35","bytes":39404,"seconds":4.841291666666667},{"speaker":"Sam","text":"The workflow has a long approval step. We may outsource one small support task as a test.","voice":"kokoro-v1-af_bella","audioUrl":"assets/dialogues/budget-and-workflow-turn-7.mp3","sha256":"4262ad4ea047fc520beaa9abedff4f3edbd93ac159d495075c8d49ca7e13660d","bytes":46508,"seconds":5.715333333333334},{"speaker":"Dana","text":"Is this for our B2B service, which sells to other companies?","voice":"kokoro-v1-af_river","audioUrl":"assets/dialogues/budget-and-workflow-turn-8.mp3","sha256":"96cbcd1717589d18635dfeffbe5f0aeb7277432c114d7fea7f0668f2bbb3e0d4","bytes":30956,"seconds":3.7746666666666666},{"speaker":"Sam","text":"Yes. The B2C service for individual customers is outside this pilot.","voice":"kokoro-v1-af_bella","audioUrl":"assets/dialogues/budget-and-workflow-turn-9.mp3","sha256":"44aba556cb713c8f5dcde6d6e846a7f829be97400796121b3db6e892180a9646","bytes":42092,"seconds":5.161958333333334},{"speaker":"Dana","text":"The existing server is an asset we can use. Please check the test cost before proposing a purchase.","voice":"kokoro-v1-af_river","audioUrl":"assets/dialogues/budget-and-workflow-turn-10.mp3","sha256":"13ab4151a9846e365e31737fde3e341dbbd812c35f2c3e3e16fbf40da3c614c6","bytes":46508,"seconds":5.717333333333333},{"speaker":"Sam","text":"I will send the draft on Thursday, including the KPI, target and approval request.","voice":"kokoro-v1-af_bella","audioUrl":"assets/dialogues/budget-and-workflow-turn-11.mp3","sha256":"14bd0bfbf6e8fff51bd19ab7e43c71ebeba820e9252d4d8828100df33c8f49e9","bytes":44396,"seconds":5.470666666666666}],"supplier-delivery-agreement":[{"speaker":"Elliot","text":"Our supply chain review shows a delay in one component. Can we discuss the sample order?","voice":"kokoro-v1-af_sky","audioUrl":"assets/dialogues/supplier-delivery-agreement-turn-0.mp3","sha256":"fc49c1d3fb948cb39c6e134538fb956add0a13f60bfd553c60ef20a2dd89ffe3","bytes":45164,"seconds":5.5452916666666665},{"speaker":"Noor","text":"Yes. Is the supplier able to provide twenty sample units?","voice":"kokoro-v1-am_onyx","audioUrl":"assets/dialogues/supplier-delivery-agreement-turn-1.mp3","sha256":"b7b5b7868fba27417f8eddb08b0d759d654f8a7dc07eab43dc1626b589b2796a","bytes":34604,"seconds":4.224666666666667},{"speaker":"Elliot","text":"The quotation covers twenty units, but it does not include freight.","voice":"kokoro-v1-af_sky","audioUrl":"assets/dialogues/supplier-delivery-agreement-turn-2.mp3","sha256":"78f16650b7d9534d183c56fed94d7d64f37d4ea866cf3beac6dc482444da6afa","bytes":31916,"seconds":3.904},{"speaker":"Noor","text":"Please list freight separately so procurement can compare the total cost.","voice":"kokoro-v1-am_onyx","audioUrl":"assets/dialogues/supplier-delivery-agreement-turn-3.mp3","sha256":"de3efbe08699b411bc25cefd479693997b024f6b484d9e42bcb9745d0840b73c","bytes":36524,"seconds":4.472},{"speaker":"Elliot","text":"The estimated lead time is ten working days after order confirmation. It is not yet a guaranteed date.","voice":"kokoro-v1-af_sky","audioUrl":"assets/dialogues/supplier-delivery-agreement-turn-4.mp3","sha256":"4e2814a02586bc2a63a7bb7a5b6f7022aae9e3c3a7c11dc8f0caf46fa4534eb2","bytes":55148,"seconds":6.814},{"speaker":"Noor","text":"Understood. We cannot send the purchase order before internal approval.","voice":"kokoro-v1-am_onyx","audioUrl":"assets/dialogues/supplier-delivery-agreement-turn-5.mp3","sha256":"70b955510e5ffe5636bc21a7fd102a7010509fc02647f6d18e4e2f430200c08e","bytes":38636,"seconds":4.739333333333334},{"speaker":"Elliot","text":"Once the order is confirmed, the shipment will contain only the sample units.","voice":"kokoro-v1-af_sky","audioUrl":"assets/dialogues/supplier-delivery-agreement-turn-6.mp3","sha256":"c76078b413e82d51fadb08e764eecbb72b867e13281879cc86eeb6cd2dbd36c8","bytes":39980,"seconds":4.905291666666667},{"speaker":"Noor","text":"Please make sure the invoice shows the agreed unit price and the separate freight charge.","voice":"kokoro-v1-am_onyx","audioUrl":"assets/dialogues/supplier-delivery-agreement-turn-7.mp3","sha256":"5a843ec698a667bb50942e31618b5a5f44e6c3a51ded61dabad1a49853c6ce74","bytes":42476,"seconds":5.216},{"speaker":"Elliot","text":"I will send the revised quotation tomorrow. Which stakeholder should receive the delivery update?","voice":"kokoro-v1-af_sky","audioUrl":"assets/dialogues/supplier-delivery-agreement-turn-8.mp3","sha256":"61ecb74b3b7cebdd0255311585445a32ee61094b5c97770a355fb1352c748d9f","bytes":44012,"seconds":5.418666666666667},{"speaker":"Noor","text":"Our procurement contact should receive it. A small sample order could be a win-win solution before a larger commitment.","voice":"kokoro-v1-am_onyx","audioUrl":"assets/dialogues/supplier-delivery-agreement-turn-9.mp3","sha256":"a042337fe4f5c174d472775026d5d79359903d5038c10d75a020aaf100c07f0d","bytes":59756,"seconds":7.39},{"speaker":"Elliot","text":"That makes sense. We can close a deal only after the price and approval are confirmed.","voice":"kokoro-v1-af_sky","audioUrl":"assets/dialogues/supplier-delivery-agreement-turn-10.mp3","sha256":"e7451d773b284399c7b2b7cd29ed00610a45088f0aec71ff5e4e1daa72d2610f","bytes":39788,"seconds":4.8853333333333335},{"speaker":"Noor","text":"Agreed. Send the price, freight and delivery estimate in writing tomorrow, and procurement will review them.","voice":"kokoro-v1-am_onyx","audioUrl":"assets/dialogues/supplier-delivery-agreement-turn-11.mp3","sha256":"48204654d89197e4c69872ae4f9a2f231bac85d7d94bb6707af74d35df0d5b2f","bytes":49772,"seconds":6.1433333333333335}]};
